package com.aiot.log.config;
import org.springframework.boot.context.properties.ConfigurationProperties; import org.springframework.stereotype.Component;
@Component @ConfigurationProperties(prefix="environment.weather")
public class EnvironmentProperties { private boolean enabled=false; private String provider="qweather"; private String apiHost=""; private String jwtKid=""; private String jwtProjectId=""; private String jwtPrivateKeyFile=""; public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public String getProvider(){return provider;} public void setProvider(String v){provider=v;} public String getApiHost(){return apiHost;} public void setApiHost(String v){apiHost=v;} public String getJwtKid(){return jwtKid;} public void setJwtKid(String v){jwtKid=v;} public String getJwtProjectId(){return jwtProjectId;} public void setJwtProjectId(String v){jwtProjectId=v;} public String getJwtPrivateKeyFile(){return jwtPrivateKeyFile;} public void setJwtPrivateKeyFile(String v){jwtPrivateKeyFile=v;} public boolean isConfigured(){return enabled && !apiHost.isBlank() && !jwtKid.isBlank() && !jwtProjectId.isBlank() && !jwtPrivateKeyFile.isBlank();} }
